/**
 * Tool descriptions written for an LLM agent reading the tool list. Keep them
 * tight — every char is in the eager-tool budget. Say what the tool does, when
 * to reach for it, and only the gotchas an agent can't see from the schema.
 */
export const descriptions: Record<string, string> = {
  // ---------- comps ----------
  list_comps: "All comps: id, name, dims, duration, fps, layer count. Pass `include` to trim it — `include: []` returns the id+name map alone, which is all orientation usually needs.",
  get_comp: "Single comp summary by id (no layers).",
  get_comp_tree: "Comp + nested layer tree, recursing pre-comps to `depth`.",
  create_comp: "Create a new comp. Returns id.",
  set_comp: "Modify a comp (name, dims, fps, duration, work area, bg). Undefined fields unchanged.",
  delete_comp:
    "Delete a comp. Reversible only via AE's Undo. The solids its layers used are project items, not part of the comp, and After Effects leaves them behind in the Solids folder — the result counts them in `unusedSolidsLeft`. Pass `purgeUnusedSolids:true` to remove, in the same undo step, the ones nothing else uses; a solid another comp still uses is kept and reported in `keptSolids` with that comp's id. Only this comp's own solids are ever considered — for the whole project's orphans use purge_unused_footage.",
  set_active_comp: "Focus a comp in the viewer/timeline.",
  duplicate_comp:
    "Copy a comp. Returns the new comp id, so you never have to find it by name. Use this instead of run_jsx + CompItem.duplicate(). By default the copy is SHALLOW, exactly like AE's own Duplicate: its precomp layers point at the same nested comps as the original, so editing one of those edits both. `deep:true` duplicates the nested comps too and re-points the copy at them — that is what 'a variant of this rig' means. A nested comp used by several layers is duplicated once and reused. `folderId` files the copy in a project folder; `nameSuffix` names the nested copies '<original><suffix>'.",
  get_current_time:
    "Read the current playhead time of a comp: time (seconds), frame (derived from time and frameRate), frameRate, plus compId/compName for orientation. `compId` is optional — omit it to read whichever comp is active in the viewer; if none is active you'll get a clear error naming that. Read-only: never moves the playhead or changes anything else.",
  set_current_time:
    "Move the playhead of a comp. Pass exactly one of `time` (seconds) or `frame` (an integer, converted as frame / comp.frameRate) — `compId` is optional and defaults to whichever comp is active in the viewer, same as get_current_time. A target outside the comp's 0..duration is refused with a clear error rather than clamped. Returns the actual resulting time/frame read back from After Effects, not just the requested value. This only moves the CTI — it does not create an Undo step, since scrubbing the timeline by hand does not either.",
  snapshot_comp:
    "Take a cheap structural fingerprint of a comp and keep it in this server's memory. Returns a snapshotId and nothing else worth tokens — call it BEFORE a write, then diff_comp afterwards to learn what the write actually did, instead of reading the comp back and comparing by eye. It records per layer: id, name, index, type, in/out/start, parent, enabled, keyframe counts, expression count, effect count; per comp: size, duration, frame rate, work area, markers. It does NOT record property values, expression text, effect parameters, masks or shape contents. Nothing is written into the AE project, and snapshots are gone when the session ends.",
  diff_comp:
    "What changed in a comp since a snapshot: layers added, removed, renamed, retimed, re-parented, keyframe counts that moved, expressions and effects gained or lost — and nothing at all for unchanged layers, which are only counted. A few dozen tokens where list_layers + get_layer_full is thousands, and it answers the three questions worth asking after a write: which layer is the new one, where did a failed script stop, and did the assembly land. Only the recorded fields are compared, so 'no differences' means none of THOSE moved, not that the comp is identical. Returns a fresh snapshotId so you can keep diffing forward.",

  // ---------- layers ----------
  list_layers: "Layers in a comp, one-line each. Use get_layer_full for details. Pass `include` to trim it — `include: []` returns just id/index/name/type, the cheapest way to learn what is in a comp.",
  get_layer_full: "Full state of one layer: transform + keyframes + expressions, effects, masks, markers, parenting, text/shape/footage extras, and sourceRect (visible bounds). Always prefer over multiple smaller queries. Bound the answer on a heavy layer: `include` picks the sections you need, `maxKeyframes` caps the keyframes per property, `shapeDepth` limits the Contents walk. Anything dropped is named and counted in the response, so a bounded read is never mistaken for a complete one. " +
    "On a shape layer, `shapeDetail: 'compact'` returns one indented line per group — `name  matchName  prop=value prop=value`, with `[3 keys]`/`[expr]` marking animated properties and `(at defaults)` a group Transform nobody has touched — which is a fraction of the size and still names every node the write tools address. Material Options (48 3D-extrusion properties per group, inert on a 2D shape layer) is left out of both forms and counted in `materialsOmitted`; pass `shapeMaterials:true` for the extruded-3D case.",
  create_text_layer:
    "Text layer with optional font/size/color/position/tracking. anchorAlign (default 'left') aligns the text by setting paragraph justification and leaving the anchor at [0,0], so position means the start of the baseline AND stays right when the text is changed later. Tracking is set to 0 unless you pass one, because AE otherwise inherits the user's Character panel. anchorAlign 'none' keeps AE's raw defaults. " +
    "The justification is read back after the write (AE 26.3 has been seen to store a different alignment from the one set — issues #93/#94): the result carries `justification` as read and `justificationReasserted` when a second write was needed, and if it still disagrees the layer is removed and the call throws, so a success result is a layer aligned the way it says.",
  create_shape_layer: "Empty shape layer; fill via add_shape_content. Position defaults to [0,0] with Anchor Point [0,0], so the layer's coordinate space IS the comp's and every vertex, rect/ellipse position and path you add afterwards is in comp pixels. (After Effects' own default is the comp centre, which silently offsets a drawing authored in comp coordinates by half a frame — pass position:'center' if you want that, or any [x,y] to place the origin yourself.) The result echoes the position and anchor point it ended up with.",
  create_solid_layer: "Solid-color layer. color is RGB 0..1.",
  create_null_layer: "Null parent layer.",
  create_adjustment_layer: "Adjustment layer — effects on it apply to layers below.",
  create_precomp_layer: "Insert an existing comp into another as a pre-comp layer.",
  create_camera_layer: "Camera. 3D layers below view through it.",
  create_light_layer: "Light (parallel|spot|point|ambient).",
  duplicate_layer: "Duplicate a layer `count` times (default 1), optionally naming every copy `newName`. Each copy has a fresh id and lands directly ABOVE the original, keeps its parent and its track-matte source, and shares the original's source item — nothing is added to the project. Returns `{sourceLayerId, sourceLayerIndex, sourceItemId, duplicates:[{layerId, index, name, sourceItemId, parentLayerId, locked}]}`, every copy re-read by id. A locked layer's copy is locked, so newName on a locked layer is refused.",
  delete_layer: "Remove a layer.",
  inspect_property_tree:
    "Read-only walk of any layer's property tree — use it to DISCOVER properties you do not already know the path or matchName of: camera and light options, Time Remap, audio levels, text animators and their selectors, every parameter of any effect including third-party plugins and the nested Compositing Options group, shape contents, masks, layer styles. Returns a flat list of nodes in timeline order, each with name, matchName, kind, depth and a `path` that set_property_values (static writes), add_keyframe, the expression tools and set_shape_property accept as-is (matchName per segment, or a 1-based index where siblings share a matchName — two Glows, two Fills — with `occurrence` saying which). Properties carry valueType, value, numKeys, canSetExpression, min/max, separation info, and with includeKeys the full key detail. A value AE will not hand to scripts (NO_VALUE section markers and buttons, CUSTOM_VALUE plugin data) is listed with valueReadable:false and the reason, never left out. `canSetExpression` is reported as AE gives it and is NOT proof a value can be written; `hidden:true` means AE will refuse a value there in the layer's current state (measured without a false positive), but its absence proves nothing — read a write back. includeHidden:false drops the hidden ones, e.g. the ~100 inert slots a text animator's Properties group always carries. Bounded: `depth` (default 4), `maxNodes` (default 250), `maxKeysPerProperty`; Layer Styles and Material/Extrusion/Plane Options are listed but collapsed by default. Every limit that bites is reported (truncated, childrenNotWalked, collapsed). Start narrow — pass `path` (e.g. ['ADBE Effect Parade'], ['ADBE Camera Options Group']) rather than walking a whole heavy layer. Paths with indices shift when siblings are added, removed or reordered: inspect again after structural edits.",
  set_property_values:
    "Set the current STATIC value of any properties on one layer, addressed by the exact `path` inspect_property_tree returned — camera Zoom/Aperture, light Intensity/Cone Angle, a text animator's Position or Opacity, any effect parameter including the second of two identical effects (its path carries the index), shape-layer properties, mask and shape paths. Workflow: inspect_property_tree → copy the path → set_property_values → (optionally) inspect again. Up to 50 updates in one call, applied in order as ONE undo step. Values take inspect_property_tree's shapes: a number (OneD, and LAYER_INDEX/MASK_INDEX as 1-based indices, 0 for none); an array of exactly the property's dimension count (a 2D layer's Position/Scale still take 3, and its Z must stay what it is — AE ignores it); a COLOR as [r,g,b,a], or [r,g,b] to keep the current alpha; a SHAPE as {vertices, inTangents, outTangents, closed} with optional mask `feather` (omit it to keep the mask's feather points). EVERY update is checked before the first write — unknown path, a group, wrong shape or dimension count, out of min/max, NO_VALUE section markers and buttons, CUSTOM_VALUE plugin data, Source Text (use set_text), markers (use add_marker), properties inspect flags hidden:true, any property that has keyframes (static only: keys are never removed — animation is keyframe tools' job), two updates hitting one property — and any problem refuses the whole call with nothing changed. Each write is then READ BACK: a value AE accepted but did not keep is a failure, and a failure rolls back the earlier writes of the call and says whether every restore was verified. AE can still refuse at runtime where nothing predicts it (a layer style that is off says nothing and refuses), which is what that rollback is for — it is restore-by-value, not a transaction, and the error says so if a restore did not land. A property under an enabled expression takes the write as its underlying value; the expression is left alone, and the result marks it expressionEnabled with the evaluatedValue that actually renders. Result per update: path, name, matchName, valueType, previousValue, actualValue (read back from AE, not echoed) and changed. Index segments in a path shift when siblings are added, removed or reordered — inspect again after structural edits. Prefer set_transform / set_text / set_mask / set_effect_param when they cover the job; reach for this when they don't.",
  set_keyframes:
    "Bulk animation: write keyframes on any properties of any layers in a comp in ONE call — a camera's Position, Orientation, X/Y/Z Rotation and Zoom over frames 150-240 is one call, not hundreds of add_keyframe calls. Each track is {layerId, path, mode, keys}; `path` is exactly what inspect_property_tree returned (effect parameters of a second identical effect, text animator properties, shape and mask paths, camera and light options). Workflow: inspect_property_tree → copy paths → set_keyframes → inspect_property_tree(includeKeys:true) to look. Each key carries exactly one of `frame` (whole comp frames from time 0, converted with the comp's frameDuration so 23.976 lands exactly) or `time` (seconds) — one or the other for the whole request — plus `value` in inspect_property_tree's shape (COLOR as all four numbers), and optionally interpolation {in,out} (linear|bezier|hold), easeIn/easeOut (one {speed,influence} per temporal dimension: 3 on Scale, 2 on TwoD, 1 on everything else incl. Position), temporalContinuous, temporalAutoBezier, spatialTangents {in,out}, spatialContinuous, spatialAutoBezier (spatial properties only, not Orientation), label. mode \"merge\" adds keys or updates the key already at that time and leaves every other key; \"replace\" makes the given keys the whole animation. A new key gets explicit defaults, never AE's neighbour-dependent ones: linear/linear, temporalContinuous and temporalAutoBezier off, label 0, and on spatial properties zero tangents, spatialAutoBezier off and spatialContinuous ON (AE's own fresh-key state — pass spatialContinuous:false to turn it off); an updated key keeps whatever you do not pass. EVERY track and key is checked before the first write — bad path, group, unkeyable or hidden property, wrong dimension count, out of range, duplicate times, two tracks on one property, contradictory metadata — and any problem refuses the whole call with nothing changed. Every track is then read back from AE; a failure rolls back every track the call touched, verified and reported (restore by value, not a transaction). One undo step. Refused: Source Text (set_text), markers (add_marker), layer/mask indices, roving (never set; a merge into a track with roving keys is refused). Keys under an enabled expression are written and the expression left alone (expressionEnabled in the result). Result per track: counts, first/last key and `changed`, read from AE — inspect for the rest.",
  set_layer: "Update layer metadata (name/enabled/locked/shy/solo/3D/blend/label/in-out/stretch/trackMatte). Undefined fields unchanged. Every enum name and the matte source are checked before anything is written, so a refused call changes nothing. trackMatte:{layerId, type} sets a matte from that source layer (above or below, never reordered); trackMatte:null clears it; the result's `trackMatte` is read back from AE. AE turns the matte source's video off and leaves it off when the matte is cleared. inPoint/outPoint/startTime/stretch go through exactly the checks, order, readback and restore of set_layer_timing (prefer that tool for timing: it also takes frames and reports before/after).",
  parent_layer:
    "Set/clear a layer's parent (parentLayerId=null to unparent). The layer stays visually put: AE's own compensation double-counts when the parent was itself re-parented in the same call, so this recomputes the world transform and corrects position/scale/rotation, reporting any correction in `correction`. Read `correction.notes` — 3D layers, cameras and lights are not corrected, and with a keyframed ancestor the fix is only exact at the comp's current time. Pass preserveTransform:false to keep the layer's own transform values instead (it jumps into the parent's space; the result says whether the local values held in `localTransformUnchanged`). A cycle, a self-parent and a locked layer are refused before anything changes. Prefer set_layer_parent for new work: the same operation with a structural result (previousParentLayerId, parentLayerId read back). This tool stays for backward compatibility.",
  reorder_layer:
    "Move a layer in the render stack. Pass exactly one destination: `beforeLayerId` puts it directly in front of (above) that layer, `afterLayerId` directly behind it, `toIndex` at an absolute 1-based position where 1 is the front and numLayers the back. `toIndex` is where the layer ENDS UP, not the slot it displaces — the two differ by one when moving down the stack. Prefer the id forms: this is the op that shifts every index below it, so an index you read earlier may already be stale. The result carries `movedFrom` and the landed `index`, read back off the layer; equal values mean it was already there. Prefer move_layer for new work — the same move by id, with the ids now above and below it in the result; this tool stays for backward compatibility and for an absolute `toIndex`.",

  // ---------- layer structure ----------
  get_layer_structure:
    "Read-only structural map of one comp, front to back: per layer its layerId, index, name, sourceType, sourceItemId/sourceItemType, parentLayerId and childLayerIds, threeDLayer, enabled, locked, shy, adjustmentLayer, guideLayer, trackMatte ({sourceLayerId, type} or null), isTrackMatte and matteForLayerIds. Reach for it before move_layer, set_layer_parent, set_track_matte or precompose_layers, and after one to confirm the result — not get_layer_full, which is per layer and heavy. Cameras and lights read null for the flags they do not have. Each layer also carries `timing`: startTime, inPoint, outPoint, duration, stretch, sourceDuration (null when the source has no length to run out of) and timeRemap {state: unsupported|off|default|custom, numKeys, hasExpression}; the comp's frameDuration and duration are at the top. Bounded by maxLayers (default 500); relationship lists are always complete.",
  move_layer:
    "Move ONE layer in the stack, by id — the preferred way to reorder layers (reorder_layer remains for backward compatibility). Exactly one destination: `beforeLayerId` (directly in front of / above that layer), `afterLayerId` (directly behind it) or `to: \"beginning\"|\"end\"`. Ids never change on a move; indexes do, so re-read with get_layer_structure rather than reuse old ones. Track mattes follow the source by id wherever it moves. A locked layer and a move relative to itself are refused before anything changes. Returns previousIndex, actualIndex, changed and the ids now above and below it, read back from AE. One layer per call; for a group, move them one by one with beforeLayerId/afterLayerId chained off each other.",
  set_layer_parent:
    "Parent a layer to another in the same comp, or unparent it with parentLayerId:null — the preferred way to parent and unparent (parent_layer remains for backward compatibility). preserveWorldTransform:true (default) keeps it where it is on screen, correcting AE's compensation where it is provably wrong (2D; see `correction.notes`). false keeps its own transform values exactly, so it jumps into the parent's space — `localTransformUnchanged` confirms the values held. Refused before anything changes: a self-parent, a cycle (the parent is already this layer's descendant — the error names the chain), and a locked layer (a locked layer CAN be a parent). 2D, 3D, null, camera and light pairings are all allowed. Returns previousParentLayerId and parentLayerId read back from AE.",
  set_track_matte:
    "Set a layer's track matte from an explicitly named source layer, or clear it with matte:null. The source may sit above or below the target and nothing is reordered; the relationship follows the source's id through any later move. Refused before anything changes: source = target, a source or target that is a camera or light, a locked target, and a layer that is not in this comp. A source can itself be matted, and one source can matte several targets. Returns the previous and current `{sourceLayerId, type}` and `hasTrackMatte`, read back from AE. AE turns the source's video off when it becomes a matte and leaves it off when the matte is cleared — `sourceEnabled` / `previousSourceEnabled` report it. Deleting a matte source clears its targets' mattes without a word.",
  precompose_layers:
    "Precompose layers by id into a new comp. moveAllAttributes:true (default) moves the layers into a comp sized like this one and recreates them there with NEW ids — the result's `innerLayers` maps old ids to new — and puts one new precomp layer (`precompLayerId`) at the topmost selected index. moveAllAttributes:false takes exactly one footage/solid/null/precomp layer, which keeps its id, effects, masks, keyframes, parent and matte and is renamed to the new comp; only its source moves. " +
    "Refused before anything changes when After Effects would silently damage the comp: a locked layer, a camera or light; with moveAllAttributes:true also a 3D layer, an adjustment layer with unselected layers below it, a parent or track matte linking a selected and an unselected layer, an expression that names a layer across the selection or refers to one by index or computed reference, an expression using index/numLayers on a layer that moves, and an effect layer-parameter crossing the selection. Select both ends of a relationship, or break it first. Expressions in OTHER comps that reach into this one are not checked. Returns newCompId, precompLayerId/Index and parentFolderId, all read back; `parentFolderId` files the new comp.",

  // ---------- layer timing ----------
  set_layer_timing:
    "Set a layer's timing by id: any of startTime/startFrame, inPoint/inFrame, outPoint/outFrame (seconds or whole comp frames — frames use the comp's real frameDuration, exact at 23.976; for each of start/in/out pass the seconds field or the frame field, not both) and stretch. Pass at least one. The three are NOT interchangeable: inPoint/outPoint TRIM what is visible and move nothing else; startTime SLIDES the whole layer — trims and every keyframe move with it; stretch RETIMES playback (200 = half speed, twice as long) and scales trims and keys about startTime. To change which source frames play when, use Time Remap (set_time_remap, then set_keyframes) — not these. " +
    "A trim you do not pass follows the layer as After Effects moves it. The whole request is checked before anything is written, and refused with nothing changed when: outPoint would not be after inPoint (AE would accept it and leave an empty layer), a footage/audio/precomp layer without Time Remap would be trimmed outside its source (AE clamps silently — the message gives the range), stretch is negative or outside 1-9900, the layer is locked, or the layer is reversed (negative stretch) and anything but a positive stretch alone is asked. Written in a fixed order (stretch, startTime, inPoint, outPoint — inPoint drags outPoint in AE), every field read back; a mismatch restores the original timing and says so. Returns before/after (seconds and frames), changedFields and frameDuration. One undo step.",
  set_time_remap:
    "Turn Time Remap on or off for one footage, audio or precomp layer (stills, solids, nulls, text, shapes, cameras and lights cannot have it — refused). Enabling creates After Effects' two default LINEAR keys, (startTime, 0) and (startTime + source length × stretch/100, source length), returned with the property path [\"ADBE Time Remapping\"]; animate it with set_keyframes at that path — values are source seconds. If AE moves the trim while enabling, it is put back and reported. " +
    "Disabling DELETES every Time Remap key. It is allowed on its own only while Time Remap is still exactly AE's default; customized keys or an expression are refused — the refusal lists what would be lost — unless discardTimeRemap:true, which reports what was discarded. An expression survives disabling as stored text and is live again on re-enable (reported). Disabling also re-clamps the trim to the source (reported). Already in the requested state: changed:false, nothing written. Locked and reversed layers are refused. One undo step.",

  // ---------- transforms ----------
  set_transform: "Set any of position/scale/rotation/anchorPoint/opacity (+3D orientation/per-axis on 3D). `time` and `keyframe:true` go together: both key every requested property at `time`, neither sets static values, and either one alone is refused. orientation/xRotation/yRotation/zRotation on a 2D layer are refused, not skipped — set_layer threeDLayer:true first. Every requested property must exist on the layer — a camera or light has no scale/opacity/anchorPoint — and every check runs before the first write, so a refused call changes nothing. `applied` lists what was written.",

  // ---------- keyframes ----------
  add_keyframe: "Keyframe at `time` on propertyPath (e.g. ['Transform','Position']). Optional in/out interpolation + ease — one influence/speed pair, expanded to however many entries the property needs (see set_temporal_ease). The count used comes back as `easeDimensions`.",
  remove_keyframe: "Remove keyframe at `time`.",
  get_keyframes: "All keyframes on a property: time, value, interpolation, ease, spatial tangents.",
  set_interpolation: "Set in/out interpolation type of a specific keyframe.",
  set_temporal_ease:
    "Set influence+speed for the in/out ease of one keyframe. Pass at least one of `easeIn`/`easeOut` — neither is refused, since it would change nothing. Pass ONE {influence, speed} pair per side and it is applied to every dimension of the property — you never size the ease array yourself. That matters because AE's own setTemporalEaseAtKey wants a per-property number of entries that is not derivable from the value (2D Scale takes 2, a shape Ellipse Size takes 3, Opacity and sliders take 1, and spatial Position takes 1 whether the layer is 2D or 3D), and the wrong count throws a bare 'parameter 2'. This derives the count, retries the alternatives, and reports what worked as `easeDimensions` — worth reading if you are also easing that property from run_jsx.",
  set_spatial_tangents: "Set in/out spatial tangents for a position-style keyframe.",

  // ---------- expressions ----------
  get_expression:
    "Expression text, enabled state and `expressionError` on a property. `expressionError` is After Effects' own message when the expression cannot be compiled or evaluated — the text of the warning banner in the AE UI — or an empty string when it runs clean. A non-empty one means the property is not being driven by that expression, whatever `enabled` says.",
  set_expression:
    "Set + enable an expression on a property, and verify it: after the write the property is evaluated and, if After Effects reports an error on it, the call THROWS with that message and the property path. So a success result means the expression compiles and runs; a failure means the text was written but AE cannot evaluate it — fix it and call set_expression again, or clear_expression to remove it. A broken expression never comes back as ok.",
  toggle_expression:
    "Enable/disable an expression without clearing. Enabling verifies the same way set_expression does: if AE reports an error on the expression once it is enabled, the call throws with the message rather than returning ok.",
  clear_expression: "Remove an expression.",

  // ---------- effects ----------
  list_effects: "All effects on a layer with current param values + keyframes/expressions.",
  add_effect: "Add effect by matchName (use list_available_effects — matchNames are stable across AE versions; display names aren't). A wrong matchName fails immediately and cheaply, so try the standard one (ADBE Gaussian Blur 2, ADBE Slider Control) before searching.",
  remove_effect: "Remove effect by 1-based index.",
  set_effect_param:
    "Set one parameter of one effect. Pass at least one of `paramName` (the display name, e.g. 'Blurriness') or `paramMatchName` (e.g. 'ADBE Gaussian Blur 2-0001'); list_effects reports both for every parameter on the layer. Give both and the matchName wins, with the name as fallback — worth doing when a display name is ambiguous or the user's After Effects is localised. `time` and `keyframe:true` go together: pass both to write a keyframed value at `time`, or neither for a static value — either one alone is refused before anything is written.",
  set_effect_enabled: "Toggle an effect on/off without removing.",
  list_available_effects: "Effects installed in this AE: displayName, matchName, category. **Always pass `filter`** to substring-search: the full list is 250-450+ entries and the cost is in returning them, not in reading them, so an unfiltered call takes seconds every time while a filtered one takes a fraction of one (measured on AE 26.3: 446 entries in 3.9s, 22 filtered in 0.17s). `refresh:true` re-reads after installing a plugin; the enumeration is cached per AE session, which is why refresh exists. Never loop over `app.effects` in run_jsx: it is slow enough to block the bridge past its timeout and looks like a crash.",

  // ---------- text ----------
  set_text:
    "Set text content + styling (font, size, fill/stroke, tracking, leading, justification). Undefined fields unchanged — and for justification that is verified, not assumed: on AE 26.3 the Source Text round trip has been seen to reset a left-aligned layer to centre when only `text` was changed (issue #93), so after writing, the justification is read back and compared with what should be there (the one you passed, or the one the layer had). If it moved it is written again on its own; if it still disagrees the call throws naming expected and actual rather than reporting a success the layer does not show. The result carries `justification` (the name read back) and `justificationReasserted` (true when the second write was needed).",
  add_text_animator: "Add a text animator group (position/scale/rotation/opacity/tracking/skew/fillColor/strokeColor). Optional range selector. Every node is read back before success is reported; if any step fails, the animator it made is removed. The result's `propertyPath` addresses the animator property for add_keyframe / set_expression — its value starts at AE's default, so set one to see any effect.",

  // ---------- shapes ----------
  set_shape_path: "Replace a shape path with new vertices/tangents/closed.",
  add_shape_content: "Add shape content under Contents or a sub-group. `content.type` picks the node (rect/ellipse/star/path/fill/stroke/trim/repeater/merge/group); the other keys set its properties by friendly name (e.g. rect: size/position/roundness; fill: color/opacity; stroke: color/width/lineCap; path: vertices/inTangents/outTangents/closed). Unknown or unsettable keys are NOT ignored — the whole node is rolled back and an error lists them, so trust a success result. Use get_layer_full to see exact property names. ORDER MATTERS: index 1 renders in FRONT and each call appends behind the last, so add front-to-back — details and dots first, big background rects last. `zOrder:'front'` can override that, but it needs an internal moveTo which has disturbed nested renders in AE 26.3, so prefer call order. A reference to one node goes stale once a sibling is added to the same group (add a Stroke and an earlier Fill reference throws 'Object is invalid'): add every node first, then address them by name.",
  set_shape_property: "Set a property on a shape content node. `time` and `keyframe:true` go together: pass both to key the value at `time`, or neither for a static value — either one alone is refused before anything is written.",

  // ---------- masks ----------
  add_mask: "Add a mask with vertices/tangents/closed/mode.",
  set_mask: "Modify mask vertices/tangents/closed/mode/inverted/expansion/feather/opacity.",
  remove_mask: "Remove a mask by 1-based index.",

  // ---------- markers ----------
  add_marker: "Add a marker on a layer (layerId) or on the comp. time + optional duration/comment/label/chapter/url/frameTarget.",
  remove_marker: "Remove a marker by 1-based index.",

  // ---------- vision ----------
  screenshot_frame: "ONE-OFF visual check of a comp. Base64 PNG. Use only at key moments — never per-frame or in a loop. To judge MOTION, pass `times` (2-6 values) and get one tiled contact sheet with the time burned into each tile: one call, one image, about the pixel cost of a single frame — always cheaper and safer than several separate calls. `time` and `times` are mutually exclusive. Confirm the numbers with get_layer_full / get_keyframes; a picture is not exact. A downsample is chosen from the comp size (per tile, for a sheet) unless you pass one — omit it, and pass downsample:1 only when you genuinely need full resolution. Not every result is an image: 'Stale frame' means AE re-served an earlier render, 'Corrupt frame' means the file AE wrote is not a whole PNG (retry at downsample 6-8, or screenshot the precomps separately), 'Render timed out' means it is still rendering (wait, don't retry immediately), and `empty:true` means every pixel is transparent — check the time, in/out points and enabled state. On a sheet, a bad tile is drawn as a marked block and named in `warning`; the rest of the sheet is still good. Never disable layers to make a frame render.",
  screenshot_layer: "ONE-OFF visual check of a single layer (solo'd) at a time. Same one-off rule and same downsample guidance as screenshot_frame. The same 'Stale frame', 'Corrupt frame', 'Render timed out' and `empty:true` non-image results apply. No `times` here — contact sheets are screenshot_frame only. Default output is genuinely transparent outside the layer (measured: alpha 0, not a white matte) — some viewers still show that as white, which can hide white/bright/glow/bloom content. Pass `background: \"black\"` or an `[r,g,b]` to composite onto a solid for that one render; omit it for the unchanged transparent default.",

  // ---------- batch ----------
  run_batch:
    "Many ops in one ExtendScript pass — far faster than the same ops as separate calls, and far fewer undo steps. " +
    "**Up to 500 ops it is exactly one undo step.** Over 500 it is chunked into a background job — this call returns a jobId at once, before the first chunk runs; finish with await_job, which blocks for the job and is where its progress is delivered (pass a progressToken on THAT call, not on this one; get_job polls without one) — and lands as **one undo step per chunk of 25** — around 24 steps for 600 ops — because After Effects discards an undo group that spans two script calls. Every result reports the measured count in `undoSteps` with a `note`: read it before you tell anyone how to undo the work, and never say \"one Cmd-Z\" for a chunked batch. " +
    "`singleUndo:true` forces one undo step at any size up to 2000 ops, by running the whole batch in one blocking call — After Effects' interface is frozen for the duration and no progress is reported, so use it only when a single Cmd-Z actually matters to the user. Over 2000 it is refused rather than freezing AE. " +
    "transactional:true (default) stops at the first error; nothing rolls back either way — the ops before it stay applied, so read the state back rather than re-running. " +
    "`diff:true` appends a structural diff of the comps the batch touched — what it added, retimed, re-parented and keyframed — and on a failure that diff rides on the error, which is the cheapest way to find where a half-applied batch stopped.",

  // ---------- explore ----------
  get_project_summary: "Project state: path, item count, active item, flat item list with type (comp | footage | solid | folder | unknown — same vocabulary as a layer's sourceType).",
  get_project_tree:
    "The Project panel as a tree: folders, comps and footage with their ids, parentFolderId and pathIds (the folder ids above each item, root 0 first). Read-only. Reach for it to find a folder to put things in, to see where an item lives, or to find leftovers such as an empty Solids folder — not get_project_summary, which is flat. Comps carry size, duration, frameRate, numLayers, usedInCount (comps placing it) and renderQueueCount; footage carries sourceKind, filePath and usedInCount; folders carry childCount. No layers — use list_layers for those. The order is deterministic (depth-first; by name case-insensitively, then id) and is not After Effects' panel order. Names are NOT unique and may repeat: always act on `id`. Bounded by depth (default 16) and maxItems (default 500); truncation says what was left out. folderId lists one folder; 0 is the root.",
  create_project_folder:
    "Create a Project panel folder (not a directory on disk) in the root (parentFolderId 0, the default) or inside another folder. Duplicate names are allowed, so keep the returned itemId — never find the folder again by name. Returns the folder as After Effects reads it back: itemId, name, parentFolderId, pathIds. One undo step.",
  rename_project_item:
    "Rename a folder, comp or footage item by id. The id never changes, and a footage item's file on disk is untouched. Duplicate names are allowed; empty or blank names are refused. The project root (0) cannot be renamed here. Returns previousName and actualName as read back from After Effects. One undo step.",
  move_project_item:
    "Move a folder (with everything in it), comp or footage item into another folder, or to the project root with folderId 0. The id never changes and nothing inside a moved folder is touched. Refused before anything changes when a folder would go into itself or into a folder inside it. Returns previousParentFolderId and parentFolderId as read back, and changed:false when it was already there. One undo step.",
  analyze_project_item_deletion:
    "Read-only: what deleting a project item would take with it. After Effects deletes without asking — a folder takes everything inside it, a comp or footage item takes every layer that uses it in every comp, and a comp takes its Render Queue items — so call this before delete_project_item and tell the user what will go. Returns every item that would be removed, the layers in other comps (externalLayers, externalComps), the Render Queue items, totals, a one-line summary, and whether delete_project_item's safe and recursive modes would allow it (with reasons). Expressions that refer to an item by name are not detected.",
  delete_project_item:
    "Delete a project item by id, refusing anything whose deletion would reach beyond it. mode \"safe\" (default) deletes only an empty folder, or a comp or footage item no layer and no Render Queue item uses — e.g. an empty Solids folder left behind after deleting comps. mode \"recursive\" also deletes a folder with everything inside it, but only when nothing outside the folder uses any of it. No mode deletes a layer in another comp or a Render Queue item: those refusals change nothing and the error carries the full impact summary. Call analyze_project_item_deletion first. Every removed id is verified gone and the project's other layers and Render Queue verified untouched. One undo step. Use delete_comp for a comp you also want its solids cleaned up with.",
  find_layers:
    "Search one comp (`compId`) or every comp for layers matching name (regex, case-insensitive), type and/or effect matchName filters. Returns `{matches, count, compsSearched, included}`; each match is id/index/name/sourceType plus compId/compName — enough to address the layer with any other tool. That is the whole record by default: pass `include` (flags, timing, parent — the same names as list_layers) to add sections to every match, and note that unlike list_layers an omitted `include` here means the bounded form, not everything. For one layer's details use get_layer_full on the id it gives you.",

  // ---------- raw ----------
  run_jsx:
    "Escape hatch: arbitrary ExtendScript in an undo group. Pass exactly one of `code` (inline) or `scriptPath` (absolute) to run a .jsx file the server reads — use the path for anything long, so the script never enters the conversation. `libraries` (absolute .jsx paths) are read by the server too and inlined ahead of the script in the same scope, so their functions are callable from it; they are re-evaluated on every call, so keep them to declarations rather than to work. Keep shared helpers there instead of pasting them into every script. " +
    "In scope: `app`, the full `OPS` table (every tool on this server, e.g. `OPS.set_transform({compId, layerId, position:[0,0]})`), and these helpers — `compById(id)`, `getCompById(id)`, `layerById(compOrId, layerId)`, `getLayerById(comp, layerId)`, `walkProperty(layer, [\"Transform\",\"Position\"])`, `addKeys(prop, [[t, v], …])` → key indices, `ease(prop, keyIndex, easeIn, easeOut)` which sizes the KeyframeEase array itself (a bare number means influence; omit easeOut for the same both sides), `shape(comp, {name, position})` which lands the layer at [0,0] rather than the comp centre, and `withoutUndoGroup(fn)`. " +
    "`app.executeCommand()` menu commands silently no-op here — they depend on host focus and the active selection, neither of which this bridge has — so use the API equivalents (`CompItem.duplicate()`, `layer.duplicate()`). " +
    "`return X` sends a value back — arrays and nested objects come back whole. Anything that cannot be JSON is replaced in place by a marker string, never dropped: `\"[function]\"`, `\"[undefined]\"`, `\"[circular]\"`, `\"[max depth]\"`, `\"[NaN]\"`, and live AE objects as `\"[CompItem \\\"Main\\\" #12]\"` — a handle to pass to a real read tool, not a walk of the object. An empty result therefore means the script really returned nothing. " +
    "A script with no explicit `return` — including one ending in a bare expression, which does NOT return its value — comes back as `{ok:true, returned:null, undoGroup, note}`. That means it ran to completion; it did **not** fail, so do not re-run it. Nothing rolls back, so re-running a mutating script applies it twice. " +
    "A failure names the line of YOUR script and prints its text; when the number cannot be mapped it says so rather than guessing. Everything before that line already ran and nothing rolls back, so read the state back — never re-run the script to see if it fails again. " +
    "AE refuses copyToComp for a layer with a parent or a linked expression while an undo group is open: call `withoutUndoGroup(function(){ … })` around just that part, or pass undoGroup:false for the whole script (its changes then land as whatever undo steps AE records on its own, not one). Keep loops short — ExtendScript is single-threaded and freezes the user's UI. " +
    "`diff:true` fingerprints the comp before and after the script and appends only what changed, so the script reports what it actually did instead of you reading the comp back; with it the answer is always `{ok, returned, diff}`. If the script throws, that diff is appended to the error — which is how you find where a half-applied script stopped, since nothing rolls back.",

  // ---------- footage ----------
  import_footage:
    "Import a file (video, image, audio, SVG, PSD/AI) into the project. Returns the item id — pass it to create_footage_layer to place it. Validates what AE actually produced: an SVG whose viewBox asks for one aspect ratio and imports at another is a known AE bug that renders as nothing with no error, so the item is deleted and the call throws with the workaround. `force:true` keeps it and reports the problem in `validation` instead.",
  create_footage_layer: "Place an imported project item into a comp as a layer. Takes the itemId from import_footage or get_project_summary. For a comp use create_precomp_layer instead.",
  purge_unused_footage:
    "Remove footage items no comp uses. By default only solids — the items behind solid and adjustment layers, which delete_comp and delete_layer leave behind in the Solids folder, so a session that builds and discards comps can leave hundreds. `solidsOnly:false` removes every unused footage item, imported files and placeholders too, which is what AE's own Remove Unused Footage does. Comps and folders are never touched: a nested comp nothing uses is not footage. " +
    "`dryRun:true` lists what would go (`wouldRemove`) without removing anything or adding an undo step — use it first on a project you did not build. `folderId` limits the sweep to one folder and its subfolders. Reports `scanned`, `inUse` and `removed` (id, name, kind); a real run is one undo step. If one removal fails, the error names it, what was already removed and what was not attempted, since nothing rolls back.",
  replace_footage:
    "Swap a FootageItem's source file in place — the revised-asset workflow (an Illustrator/SVG/PNG/video file gets updated, AE needs to point at the new one) without touching anything downstream. `itemId` (from import_footage or get_project_summary) keeps its id, and every layer, transform, effect, keyframe, parent and expression that already referenced it keeps referencing it — this is not delete-and-reimport-and-relink. Only works on footage that already came from a file: a solid, a placeholder, a comp or a folder is refused, not silently converted. `filePath` is validated to exist before AE ever touches the item, so a bad path never reaches it and the old source is untouched. width/height/duration/frameRate in the result are read back from AE after the swap, not computed — that is what actually changed. `sequence:true` replaces with a numbered image sequence starting at `filePath`, same convention as import_footage's own flag. `usedIn`/`layerCount` name what already points at this item, read fresh from AE, not tracked by this server.",

  // ---------- render queue (Phase 1: inspect and enqueue, never render) ----------
  get_render_queue:
    "Read the Render Queue: every item's comp, status, render flag, time span and output modules. `queueIndex` is current position, not a persistent id — After Effects gives render-queue items neither an `.id` nor a working `.index`, and removing an earlier item renumbers everything after it. `status`/`statusCode` are After Effects' own RQItemStatus (QUEUED, NEEDS_OUTPUT, RENDERING, DONE, ERR_STOPPED, USER_STOPPED, WILL_CONTINUE, UNQUEUED). Each output module reports the file path, name and extension AE actually has set, plus `fileExists` — read fresh every call, never cached. Nothing here starts, pauses or cancels a render; there is no render/cancel/progress capability yet.",
  queue_comp:
    "Add a comp to the Render Queue — inspection and setup only, this never renders anything. Rejects a nonexistent item and anything that is not a comp. `outputPath`, if given, sets Output Module 1's file; After Effects may silently rewrite its extension to match the active output-module template (ask for `.mov` against an H.264 module and the readback is `.mp4`), so trust the returned `outputs[]`, never an echo of what you passed. The path's parent directory must already exist — this never creates one, and rejects before touching the queue if it does not. Omitting `outputPath` leaves the output module at whatever this AE session queued last, which is inherited from prior use, not blank and not specific to this comp — check `outputs[]` before assuming it is sensible. The same comp may be queued more than once; nothing is deduplicated, and each call returns its own `queueIndex`. If setting the output module fails after the item was added, the item is removed before the error is raised — never leaves a half-configured item behind. Render Queue changes are not part of After Effects' Undo stack, so this is not one Ctrl+Z.",

  // ---------- audio ----------
  place_audio_cues:
    "Score a scene in one call: a list of cues, each a sound at a comp time with a level in dB, becomes one audio layer each — imported if needed, named, trimmed, labelled — in a single undo step. Reach for it whenever you are placing more than two or three sound effects; the alternative is dozens of round trips or a run_jsx loop that has to know that `layer.property('ADBE Audio Levels')` returns null on an audio layer. " +
    "Every cue names its sound with **exactly one** of `path` (a file to use — imported once however many cues name it, and an item already in the project from that path is reused) or `footageId` (one already imported); both together, or neither, is reported against that cue's index with nothing placed. `time` is when the cue starts; `levelDb` is decibels (0 = the file as recorded, negative = quieter), defaulting to 0. `inPoint`/`outPoint` trim in COMP time, not file time. " +
    "Three per-cue options cover what scoring passes otherwise redo in run_jsx: `loop:true` repeats the sound to `outPoint` or the comp's end (time remapping plus a wrap-around expression on Time Remap; AE's own remap keyframes are kept, since removing them breaks the property); `fadeIn`/`fadeOut` in seconds put Audio Levels keyframes at the layer's real in/out, fading between `fadeFloorDb` (call-level, default -48) and `levelDb`; `stretch` is a percentage (100 unchanged, 200 half speed and lower pitch) and the start time and trims are re-asserted after it. A loop that is also stretched has the factor baked into its expression, so changing stretch by hand later leaves the loop at the old rate. A fade longer than the cue's placed length, a stretch of 0 or below, or a floor at or above the cue's level is refused by cue index with nothing placed; for a file not yet imported the fade is checked right after the import, before any layer exists. " +
    "It is all-or-nothing: every cue is validated — file exists, item has audio, time inside the comp, options sane — before a single layer is made, and if a later one still fails, everything this call created is removed and the error names the cue. The result carries one small entry per cue (layerId, name, time, plus `looped`/`stretch`/`fadeIn`/`fadeOut` and read-back in/out only where an option set them) and `sources` naming what was imported or reused — not an echo of the request. Use `dryRun:true` to check a cue list against the project without touching anything, including the undo stack; it answers with counts, `wouldImport`, `wouldReuse` and the failing cues by index, never the whole resolved list. Max 200 cues per call.",

  // ---------- motion graphics templates ----------
  export_mogrt:
    "Export a comp as a .mogrt for Premiere. Handles the three things that make a scripted export look like a hung connection: it saves the project first (removes AE's modal save prompt), suppresses the modal font warning that otherwise freezes this connection until someone clicks OK in AE, and runs outside the undo group. " +
    "**The comp needs at least one property in its Essential Graphics panel** — After Effects will not build a template from an empty one, and it refuses silently, so this tool checks the controller count first and refuses before exporting rather than reporting a cause it cannot know. Fix it in AE: Window > Essential Graphics, pick the comp, drag a layer property in. " +
    "`name` defaults to the comp name — AE's own default is the literal 'Untitled', so every export would otherwise overwrite the same file. Pass `posterTime` to render that frame as the template's thumbnail, replacing the black one AE writes; the export still succeeds if only the thumbnail fails. Needs the project saved once by hand first. `fonts` in the result lists the fonts the template will require — tell the user, since non-Adobe ones make Premiere flag the template. " +
    "If an export still fails, read the message before acting: it lists what was checked, and it only names a modal dialog when dialogs were left unsuppressed. Under the default suppression a dialog is impossible, the cause is genuinely unknown, and the way to see AE's own reason is for the user to run the same export by hand from the Essential Graphics panel.",

  // ---------- house style ----------
  get_house_style:
    "The user's palette, type, motion and layout defaults for the project that is open, read from `house-style.md` beside the .aep. Call it once before building anything so your work matches the rest of theirs. Returns a few-hundred-token summary by default — palette as named hexes, type, motion, layout, and a note naming anything it could not summarise; pass `detail:'full'` for the whole document, which you need before editing the guide with set_house_style. `found:false` means none exists yet — build with sensible defaults and offer to capture one afterwards. Cheap; never a reason to skip.",
  set_house_style:
    "Write the project's style guide. Replaces the whole file, so read it first and send the merged document — `overwrite:true` is required to replace an existing one. The project must have been saved at least once, since the file lives beside the .aep. Use the style-guide topic of ae_guide for how to capture a style worth writing down.",

  // ---------- guidance ----------
  ae_guide:
    "The full working guidance for these tools, by topic. Read `after-effects` before a first substantial build in a session, `style-guide` when capturing or editing the user's look, `ae-setup` when a tool cannot reach After Effects, `whats-new` when a call behaves differently from what you expected. Covers the traps that silently produce wrong output and are not visible from any single tool's schema. `whats-new` is one section per release, newest first, each entry leading with the rule as it now stands and a `supersedes:` line quoting the old rule a project's notes may still carry; pass `since` (a version, e.g. '0.4.0') to get only the releases after it, or one line saying nothing is newer — that is how the absorb-release prompt brings a project's docs up to date once per upgrade. The whats-new answer always opens with this server's own version. `since` is rejected on any other topic.",

  // ---------- jobs ----------
  await_job:
    "Block until a chunked run_batch job is done. Default 10min timeout. Returns the same payload the tool would have, `undoSteps` included. " +
    "**This is the call that carries progress**: send it with a progressToken and notifications/progress arrive while it waits, every one before its response. run_batch's own response is back before the first chunk runs, so no progress can ride on that call — a token there is ignored.",
  get_job:
    "Non-blocking job status: progress/total/state/error. Poll this when you cannot keep an await_job open. It never sends notifications/progress — that is await_job's job.",
  cancel_job: "Set cancel flag; chunked loop stops at next boundary.",

  // ---------- setup ----------
  check_setup: "Diagnose the After Effects connection: panel installed, up to date, the version AE is actually running, Adobe debug preference on, AE running, bridge answering — on whichever port it answers, since the port file is only a hint — plus `portAgreement` (do tool calls go to the port the panel answers on?) and, when nothing answers at all, `panelSignature` (did CEP's own log say it refused to load the panel?). Read-only and safe to call any time. Call this FIRST whenever another tool reports it cannot reach After Effects or says the panel is out of date, then relay `nextSteps` to the user in plain language. `panelRunningCurrent` is the one that predicts whether calls will work — it can fail while `panelUpToDate` passes, which means an update is installed but AE has not been restarted. A failing `portAgreement` means the server's port went stale, not the panel: retry the call (the server re-discovers the port whenever a call is refused) or reconnect the MCP server — never restart After Effects for it, a panel is listening. A failing `panelSignature` means no restart and no reinstall will help; `nextSteps` carries the self-signing fix.",
  setup_panel: "Install or refresh the After Effects panel and enable the Adobe preference AE needs to load it. Run this when check_setup reports the panel is missing, out of date, or older than what AE is running. It writes to the user's Adobe CEP extensions folder and sets two user-level Adobe preferences — PlayerDebugMode, and CEP's LogLevel where it was never set, so that if AE ever refuses to load the panel its CEP log says why — tell the user what it will do before calling it. Prefer running it while AE is CLOSED: the panel then loads when they open it, with no restart. If AE is already open they must quit and reopen it, and until they do, the old panel keeps answering. If the preference was newly enabled, a one-time Mac reboot may also be needed. If the existing install had been self-signed (check_setup's `panelInstalled` says so), the fresh copy is unsigned and the result says the signing has to be redone — on a machine that needed signing, tell the user before calling this.",
  init_project:
    "Set up a working folder for one video, series or client: a project brief and a pointer to the house style, written in whichever layout this client reads. Run it when the user is starting out or asks to set up a project. It writes files to disk — say which folder before calling, and pass `dir` explicitly unless the client already told the server where it is working. It never overwrites anything and reports every path it wrote. AGENTS.md carries a `Tools version last absorbed: <version>` line stamped with this server's version; the absorb-release prompt reads it after an upgrade to apply only what changed since, then moves it on — leave the line in place.",

  // ---------- issue journal ----------
  list_known_issues:
    "Problems earlier sessions hit with these tools, with the workarounds that worked. You do not need to read this ahead of time: a failed call names the entries that match its tool and error text in the error itself, under `Known from earlier sessions:`. Call this when you are planning something that has bitten before (pass `tool` or `query`), when a failure's pointer names an entry you want to open, or when the user asks what is known. Merges two journals and tags every entry with the one it came from: `project` (or `home`, the fallback when there is no project folder) for this project's own notes, `user` for tool and After Effects behaviour carried across every project. Returns a one-line index by default, entries naming `tool` first and then most recently seen first; the cause and the workaround are in the entry, so follow up with `id` on anything that looks like your problem — ids are unique only within a journal, so use the `scope:id` form the `next` pointer shows. Archived entries (not seen for 30 days, last seen on an older server, or retired with archive_issue) are hidden and counted in `archivedCount`; `includeArchived:true` lists them, and an `id` read always works. `detail:'full'` dumps every matching entry and is rarely worth it. Also returns the repo and server version needed to report one.",
  log_issue:
    "Record a problem you hit and the workaround that got past it, so the next session doesn't rediscover it. Log only what cost real effort and will recur: a tool failing for a non-obvious reason, an argument shape the schema didn't imply, AE behaving unlike the docs. Not your own typos, not one-off user mistakes. Pass `tools` and the exact `errorText`: that is what lets a later failure be answered with this entry, and it is what merges a re-log into the existing entry even under a different title (the result says `mergedBy` and keeps the existing title). Reusing an existing title extends it too. Pass `kind:'ae-quirk'` for a permanent After Effects behaviour, so a new release does not archive it as fixed; the default `tool-bug` is presumed fixed once it was last seen on an older server than the one running. Choose the scope by what the entry is *about*: leave it at the default `project` for this project's footage, comps or files, and pass `scope:'user'` when it is about how these tools or After Effects behave, so the next project starts already knowing it. If the result says `reopened:true`, an entry that had been retired is back — tell the user the problem was supposed to be gone. If the result comes back with reported:false, then AFTER you have finished the actual work, close your reply by telling the user in plain language that something took much longer than it should have and offering to pass it to the people who maintain this tool — phrase it for a motion designer, in terms of what actually happened, and don't say 'GitHub issue' or 'bug report' unless they say it first.",
  mark_issue_reported:
    "Record that a journal entry has been sent to the maintainers, with the resulting URL. Call it only once the issue really exists, so later sessions don't ask the user to report the same thing twice.",
  archive_issue:
    "Retire a journal entry for good: it leaves the index (and the pointers a failed call shows still name it, marked archived with this reason) but the file stays, hand-editable, with `reason` in its frontmatter. Use it when a report already covers the problem (pass that URL as the reason), when a release fixed it, or when the lesson has been moved into the project's own notes. Entries that merely go quiet archive themselves — 30 days unseen, or last seen on an older server — so this is for a decision, not for tidying. Use the scope-qualified id (`user:my-entry`) when both journals hold the slug; only the one named moves. A later log_issue with the same title or the same tool and error text brings it back and says so.",
};
